import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CWgsre3x.js";const u=JSON.parse('{"title":"Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"release-notes/index.md","filePath":"release-notes/index.md"}'),o={name:"release-notes/index.md"};function r(s,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="release-notes" tabindex="-1">Release Notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release Notes&quot;">​</a></h1><p>For the version-by-version record see <a href="/changelog/">Changelog</a>. The newer summaries below reflect published release records, not confirmation of production activation.</p><h2 id="v0-7-26-—-2026-11-27" tabindex="-1">v0.7.26 — 2026-11-27 <a class="header-anchor" href="#v0-7-26-—-2026-11-27" aria-label="Permalink to &quot;v0.7.26 — 2026-11-27&quot;">​</a></h2><p>Graphical fleet tracking and offline geographic canvas, independent journey legs, persistent flight and ferry identities, timestamped manual observations, arrival advisories, dispatcher-reviewed pickup changes and chauffeur briefs.</p><p><strong>Availability:</strong> Automatic external flight/ferry monitoring, background scheduling, complete quota enforcement, licensed street maps and physical mobile GPS remain outstanding; external providers and public intake disabled.</p><h2 id="v0-7-25-—-2026-11-26" tabindex="-1">v0.7.25 — 2026-11-26 <a class="header-anchor" href="#v0-7-25-—-2026-11-26" aria-label="Permalink to &quot;v0.7.25 — 2026-11-26&quot;">​</a></h2><p>Persistent notifications and retries, transactional conversation conversion, subcontractors and leg assignments, supplier settlements, profitability, AADE/myDATA and EDXEIX sandbox records, manual arrival advisories and update preservation.</p><p><strong>Availability:</strong> External providers, automated arrival monitoring, physical GPS, live regulatory submission and customer installations outstanding.</p><h2 id="v0-7-24-—-2026-11-26" tabindex="-1">v0.7.24 — 2026-11-26 <a class="header-anchor" href="#v0-7-24-—-2026-11-26" aria-label="Permalink to &quot;v0.7.24 — 2026-11-26&quot;">​</a></h2><p>Opt-in chauffeur GPS, geofences, optional Google map, Places and Geocoding, Routes estimates and return legs; notification, multilingual booking, subcontractor and regulatory sandbox foundations.</p><p><strong>Availability:</strong> External activation, physical mobile acceptance, live regulatory submission and customer installations deferred.</p><h2 id="v0-7-23-—-2026-11-26" tabindex="-1">v0.7.23 — 2026-11-26 <a class="header-anchor" href="#v0-7-23-—-2026-11-26" aria-label="Permalink to &quot;v0.7.23 — 2026-11-26&quot;">​</a></h2><p>Standalone customer booking gateway, authoritative quotes, phone-only booking, automatic CRM linkage, independent chauffeur journeys, partial cash collection and audited handover.</p><p><strong>Availability:</strong> Public booking and external delivery disabled pending approval.</p><h2 id="v0-7-22-—-2026-11-26" tabindex="-1">v0.7.22 — 2026-11-26 <a class="header-anchor" href="#v0-7-22-—-2026-11-26" aria-label="Permalink to &quot;v0.7.22 — 2026-11-26&quot;">​</a></h2><p>Commercial hardening improves cash custody, chauffeur access safeguards, passenger privacy, AI data minimization and automated validation.</p><p><strong>Availability:</strong> publication does not confirm installation or commercial activation.</p><h2 id="v0-7-21-—-2026-11-26" tabindex="-1">v0.7.21 — 2026-11-26 <a class="header-anchor" href="#v0-7-21-—-2026-11-26" aria-label="Permalink to &quot;v0.7.21 — 2026-11-26&quot;">​</a></h2><p>AI privacy minimization and local reconstruction of contact details; CRM recognition, conflicting contact detection, passenger lifecycle notifications and company onboarding readiness. Atomic conversation persistence with rollback protection; human dispatcher takeover, conversation ownership enforcement and protected saved-location selection and private CRM preferences.</p><p><strong>Availability:</strong> publication does not confirm installation or commercial activation.</p><h2 id="v0-7-20-—-2026-11-25" tabindex="-1">v0.7.20 — 2026-11-25 <a class="header-anchor" href="#v0-7-20-—-2026-11-25" aria-label="Permalink to &quot;v0.7.20 — 2026-11-25&quot;">​</a></h2><p>Fast customer lookup, returning-passenger recognition, phone-only booking with optional email, cash-first operator workflow, partner commission estimation and passenger-safe booking summaries; messaging channel foundations. Company onboarding, AI Copilot continuity, booking status and tariff presentation, and clipboard feedback.</p><p><strong>Availability:</strong> publication does not confirm installation or commercial activation.</p><h2 id="v0-7-19-—-2026-11-25" tabindex="-1">v0.7.19 — 2026-11-25 <a class="header-anchor" href="#v0-7-19-—-2026-11-25" aria-label="Permalink to &quot;v0.7.19 — 2026-11-25&quot;">​</a></h2><p>Chauffeur journey and amendment safeguards, partial and full cash collection, collecting chauffeur attribution, reconciliation and handover, CRM and repeat bookings, concierge partner reservations, AI operations and onboarding readiness. Update failure detection, installation monitoring timeout recovery and safer retry verification.</p><p><strong>Availability:</strong> publication does not confirm installation or commercial activation.</p><h2 id="v0-7-18-—-2026-11-25" tabindex="-1">v0.7.18 — 2026-11-25 <a class="header-anchor" href="#v0-7-18-—-2026-11-25" aria-label="Permalink to &quot;v0.7.18 — 2026-11-25&quot;">​</a></h2><p>Independent outbound and return assignments, separate chauffeur progress, driver cash confirmation, printable trip vouchers, expanded reporting and company readiness checklist. Update Now interface, header update notification, installation monitoring, compact diagnostics, cash handover, dispatch conflict detection, booking and AI Copilot.</p><p><strong>Availability:</strong> publication does not confirm installation or commercial activation.</p><h2 id="v0-7-17-—-2026-11-25" tabindex="-1">v0.7.17 — 2026-11-25 <a class="header-anchor" href="#v0-7-17-—-2026-11-25" aria-label="Permalink to &quot;v0.7.17 — 2026-11-25&quot;">​</a></h2><p>Dispatch scheduling and crew selection, return calendar visibility, chauffeur dashboard, outstanding cash balances and cash receipt confirmation. Driver-to-office cash handover and daily cash management summaries.</p><p><strong>Availability:</strong> publication does not confirm installation or commercial activation.</p><h2 id="v0-7-16-—-2026-11-25" tabindex="-1">v0.7.16 — 2026-11-25 <a class="header-anchor" href="#v0-7-16-—-2026-11-25" aria-label="Permalink to &quot;v0.7.16 — 2026-11-25&quot;">​</a></h2><p>PostgreSQL parameter typing in partner reservation amendments; preserved authoritative contracted pricing and commission calculations.</p><p><strong>Availability:</strong> publication does not confirm installation or commercial activation.</p><h2 id="v0-7-15-—-2026-11-25" tabindex="-1">v0.7.15 — 2026-11-25 <a class="header-anchor" href="#v0-7-15-—-2026-11-25" aria-label="Permalink to &quot;v0.7.15 — 2026-11-25&quot;">​</a></h2><p>Return and hourly chauffeur amendments, authoritative return discounts, partner pricing and commissions, payment ledger and balances, cash reconciliation, chauffeur dashboard, phone lookup, passenger privacy, Website Studio, conversational handoff and Command Center metrics. Email remains optional.</p><p><strong>Availability:</strong> publication does not confirm installation or commercial activation.</p><h2 id="v0-7-14-—-published-release" tabindex="-1">v0.7.14 — published release <a class="header-anchor" href="#v0-7-14-—-published-release" aria-label="Permalink to &quot;v0.7.14 — published release&quot;">​</a></h2><p>The published release describes responsive Schedule &amp; Dispatch improvements, date navigation and calendar presentation, contracted partner pricing and booking attribution, passenger special requests and internal dispatch notes, authorized dispatch overrides with mandatory audit justification, server-side Website Studio draft and revision improvements, and conversational reservation handoff improvements. Passenger email remains optional.</p><p><strong>Release evidence:</strong> canonical commit <code>bb02dba6eed8c118f86c6a901f569a4da0033067</code>; the annotated release tag was verified. The release record reports four passing canonical CI workflows, centralized version consistency tests and preservation of historical database migrations; no new migration is required by this release.</p><p><strong>Availability:</strong> published release, not independent evidence of deployment or live acceptance. Public publication and external provider activation remain gated. English-first functional development continues.</p><h2 id="v0-7-13-—-published-staging-release" tabindex="-1">v0.7.13 — published staging release <a class="header-anchor" href="#v0-7-13-—-published-staging-release" aria-label="Permalink to &quot;v0.7.13 — published staging release&quot;">​</a></h2><p>Integrated commercial modules, commercial analytics, payment provider readiness, enhanced operator administration and booking workflows, public booking gateway and passenger lookup foundations, and Website Studio / Template Manager integration.</p><p><strong>Release evidence:</strong> the release record reports six additional staging database migrations and scoped permissions, and four passing canonical CI workflows. Activation of public booking or external integrations requires separate configuration and acceptance.</p><h2 id="v0-7-12-—-published-staging-release" tabindex="-1">v0.7.12 — published staging release <a class="header-anchor" href="#v0-7-12-—-published-staging-release" aria-label="Permalink to &quot;v0.7.12 — published staging release&quot;">​</a></h2><p>Authenticated website design preparation supports larger requests through a dedicated protected endpoint while preserving ordinary API limits. Tenant authorization and role checks precede design processing; malformed or oversized requests receive improved handling. Hosting, HTTPS and publishing safeguards and independent design studio compatibility are retained.</p><p><strong>Release evidence:</strong> the release record reports five passing canonical CI acceptance jobs, a signed release tag, PostgreSQL tenant isolation verification and no new database migrations. No automatic public website changes or live booking or payment activation are implied.</p><h2 id="v0-7-11-—-controlled-staging-release-24-november-2026" tabindex="-1">v0.7.11 — controlled staging release (24 November 2026) <a class="header-anchor" href="#v0-7-11-—-controlled-staging-release-24-november-2026" aria-label="Permalink to &quot;v0.7.11 — controlled staging release (24 November 2026)&quot;">​</a></h2><p>The release introduces integrated Website Studio publishing capabilities: hosting management, HTTPS verification, compilation of a selected website design, private revision preparation, verified backups and owner-authorized website updates and rollback. It includes single-use authorization and recovery protections and maintains independent local design studio compatibility.</p><p><strong>Availability:</strong> published software release for guarded staging deployment only. This is not evidence of an active customer website, live booking or payment processing. The release does not include database migrations or production website changes.</p><h2 id="v0-7-10-—-controlled-staging-release-24-november-2026" tabindex="-1">v0.7.10 — controlled staging release (24 November 2026) <a class="header-anchor" href="#v0-7-10-—-controlled-staging-release-24-november-2026" aria-label="Permalink to &quot;v0.7.10 — controlled staging release (24 November 2026)&quot;">​</a></h2><p>Website Studio refinements include improved visual editing and responsive previews, multilingual reference websites (English, Greek, Italian, French, German and Spanish), block and inspector editing, local draft autosave, backup and recovery, tenant-isolated draft storage, portable <code>.tbsite.json</code> and <code>.tbtheme.json</code> packages and improved navigation between Website Studio and Theme Manager.</p><p><strong>Availability:</strong> published software release for controlled staging deployment only. Public website publication, server-backed website persistence requiring migration 020, live payments and external booking integrations were not activated by this release.</p><h2 id="v0-7-9-—-source-baseline" tabindex="-1">v0.7.9 — source baseline <a class="header-anchor" href="#v0-7-9-—-source-baseline" aria-label="Permalink to &quot;v0.7.9 — source baseline&quot;">​</a></h2><p>Multi-page local-first Website Studio, responsive preview, portable website and theme packages, and tenant/mode-scoped drafts. Database activation and publication are distinct acceptance steps.</p><h2 id="v0-7-8-—-historical-staging-baseline" tabindex="-1">v0.7.8 — historical staging baseline <a class="header-anchor" href="#v0-7-8-—-historical-staging-baseline" aria-label="Permalink to &quot;v0.7.8 — historical staging baseline&quot;">​</a></h2><p>The release records describe retry-safe reservation creation, optional passenger email, duplicate booking prevention and explicit messaging consent. Staging acceptance does not establish public commercial availability.</p><h2 id="version-policy" tabindex="-1">Version policy <a class="header-anchor" href="#version-policy" aria-label="Permalink to &quot;Version policy&quot;">​</a></h2><p>These notes record published and historical versions, not the current installed version or commercial availability. Other guides retain their own reference version until reviewed against a newer release. Confirm the actual version and enabled capabilities before applying instructions.</p>',60)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
